      scss: '.selection-state {\n  padding: var(--cds-global-layout-space-sm);\n  margin: 0;\n  height: calc(10 * var(--cds-global-space-12));\n  overflow: hidden auto;\n}\n',
      hasLogic: true,
      files: { 'data/files.ts': FILES['data/files.ts'] },
