  lazyRecursive: {
    id: 'tree-view/lazy-recursive',
    title: 'Lazy-loading recursive tree',
    targets: ['website', 'demo'],
    component: TreeViewLazyRecursiveExample,
    showStyles: true,
    source: {
      html: '@if (root$ | async; as files) {\n<clr-tree [clrLazy]="true">\n  <clr-tree-node\n    *clrRecursiveFor="let file of files; getChildren: getChildren"\n    [clrExpandable]="file.isFolder"\n  >\n    <clr-icon [shape]="file.isFolder ? \'folder\' : \'file\'"></clr-icon>\n    {{ file.name }}\n  </clr-tree-node>\n</clr-tree>\n}\n',
      ts: "import { AsyncPipe } from '@angular/common';\nimport { Component } from '@angular/core';\nimport { ClrIcon, ClrTreeViewModule } from '@clr/angular';\nimport { of, timer } from 'rxjs';\nimport { map } from 'rxjs/operators';\n\nimport { File, files } from './data/files';\n\n@Component({\n  selector: 'app-example',\n  templateUrl: './example.component.html',\n  imports: [AsyncPipe, ClrIcon, ClrTreeViewModule],\n})\nexport class ExampleComponent {\n  root$ = of(files);\n\n  folderService = {\n    getFiles: (folder: File) => timer(1000).pipe(map(() => folder.files)),\n  };\n\n  getChildren = (folder: File) => (folder.isFolder ? this.folderService.getFiles(folder) : null);\n}\n",
      hasLogic: true,
      files: { 'data/files.ts': FILES['data/files.ts'] },
    },
  },
